import {escapeText as esc,icon} from './assets.js';
import {areas,placeRegistry} from './venue-registry.js';
export function restaurantMarkup(venues,active='all'){
 const list=placeRegistry.filter(v=>active==='all'||(active==='commercial'?v.kind==='district':v.areaId===active));
 return `<section class="campus-intro"><div class="campus-copy"><span class="kicker">郑州大学主校区</span><h2>四个生活区，<br>还有熟悉的商业街。</h2><p>六家餐厅与一个街区，慢慢找喜欢的去处。<br>位置资料供参考，实际商户、营业与供应请到现场确认。</p><button class="text-button campus-shortcut" data-action="venue-area" data-value="commercial">去看看商业街 ${icon('arrow')}</button></div><div class="campus-graphic" aria-hidden="true"><svg viewBox="0 0 400 240"><path d="M20 205h360M65 205V94l78-38 78 38v111M78 94h130M116 205v-60h55v60M235 205V76l63-25 63 25v129M247 78h102M255 112h23m37 0h23m-83 34h23m37 0h23M92 116h22m57 0h22M87 182v-27m108 27v-27"/><path class="graphic-sun" d="M36 44a25 25 0 1 0 50 0 25 25 0 1 0-50 0"/><path d="M35 205v-55m-16 18 16-24 16 24M376 205v-37m-13 11 13-19 13 19"/></svg><span>每一餐，都能找到熟悉的地方</span></div></section>
 <div class="venue-tabs" role="group" aria-label="生活区与街区"><button data-action="venue-area" data-value="all" aria-pressed="${active==='all'}">全部地点 <span>${placeRegistry.length}</span></button>${areas.map(a=>`<button data-action="venue-area" data-value="${a.id}" aria-pressed="${active===a.id}">${a.name}<span>${placeRegistry.filter(v=>v.areaId===a.id).length}</span></button>`).join('')}<button data-action="venue-area" data-value="commercial" aria-pressed="${active==='commercial'}">商业街</button></div>
 <div class="venue-grid">${list.map(v=>{const area=areas.find(a=>a.id===v.areaId),district=v.kind==='district',info=district?v:venues.find(a=>a.area===area.name);return `<article class="venue venue-${v.areaId}${district?' venue-commercial':''}" data-place-id="${v.id}"><div class="venue-top"><span class="venue-area">${area.name}${district?'街区资料':'生活区'}</span><span class="venue-badge" aria-hidden="true">${district?'街':area.name[0]}</span></div><h3>${v.name}</h3><p class="location">${icon('pin')}${esc(info?.location??'主校区'+area.name+'生活区')}</p><p class="venue-description">${esc(info?.description??'餐厅位置资料，可参考学校后勤公告。')}</p><details class="venue-source"><summary>位置资料与来源 ${icon('arrow')}</summary><p>资料查阅：${esc(info?.checkedAt??'2026-10-23')}。不提供未经核对的营业时间、价格或菜单。</p>${info?`<a href="${esc(info.source)}" target="_blank" rel="noopener noreferrer">${esc(info.sourceTitle)}</a>`:''}${district?`<p>详细位置出自2025年8月31日生活指南，属于历史位置参考，不确认当前具体商户。</p><a href="${esc(v.historicalSource)}" target="_blank" rel="noopener noreferrer">2025年新生生活指南：商业街段落</a>`:''}</details></article>`;}).join('')}</div><div class="inspiration-disclaimer">${icon('bowl')}<p>菜品灵感与地点资料分开。抽到的菜品不保证在这些地点出售，实际供应请到店查看。</p><a class="text-button" href="#/menu?scope=all">去逛菜品灵感 ${icon('arrow')}</a></div>`;
}
